from __future__ import annotations

from typing import Any

from shopping_agent.domain.schemas import Constraint
from shopping_agent.ranking.precise_features import build_global_idf, extract_batch_features

# Fitted from data, not hand-picked. Generated by
# scripts/fit_precise_reranker_weights.py: a class-balanced logistic
# regression over the same 13 features FallbackReranker/PreciseReranker
# already compute, trained on evaluator/local_evaluator.py sessions built
# from data/public_set.jsonl[100:200] (target parent_asin = positive label),
# and validated on the disjoint [0:100] holdout.
#
# v3 (superseded): default sklearn regularization (C=1.0) -- TechnicalScore
# 0.642464 vs FallbackReranker's 0.634392 on the holdout (+0.008, a real but
# statistically fragile win: 5000-resample bootstrap 95% CI [-0.047, +0.061],
# only 60.6% of resamples favored it).
#
# v4 (current): grouped 5-fold CV over the training rows showed held-out
# classification AUC kept improving as C increased (0.9245 at C=1.0 up to
# 0.939 at C=30, still rising at C=100) instead of the expected U-shape --
# i.e. the default C=1.0 regularization was actually too strong for this
# feature set. Re-fit at C=100 and validated on the same disjoint holdout:
# TechnicalScore 0.662590 vs FallbackReranker's 0.634392 (+0.028, bootstrap
# 95% CI [-0.027, +0.083], 84.1% of resamples favored it -- markedly more
# robust than v3). On the official 200-sample set: 0.678694 vs 0.653419
# (+0.025275), and notably the clean-holdout win (+0.028) is *larger* than
# the in-sample-training-half win (+0.022), the opposite pattern from v3 --
# i.e. this is not an overfitting artifact. Full breakdown, the CV sweep, and
# the bootstrap methodology are in docs/precise_reranker_change_report.md.
#
# Caveat: exact_matches and partial_matches are still negative and
# budget_penalty is still ~0 (same multicollinearity story as v3 -- only 100
# training sessions, ~306 positive rows out of 180k). Looser regularization
# also means larger raw magnitudes (rrf_raw=266, partial_matches=-60) than
# v3's; that is expected at high C and is why this was validated on a
# disjoint holdout rather than trusted from training performance alone, but
# it does mean these coefficients would likely shift again with more
# training sessions -- treat this as "beats v3 on held-out data today", not
# as a finished, interpretable model. A sign-constrained fit was also tried
# earlier (see change report) and performed worse (0.566) -- not used.
DEFAULT_WEIGHTS: dict[str, float] = {
    "exact_matches": -0.3593254966381364,
    "partial_matches": -60.376664049001725,
    "category_match": 1.0394807105122161,
    "term_coverage": 2.4449026807580445,
    "lexical_signal": 2.482095725827034,
    "rrf_raw": 265.705713751426,
    "dense_raw": -6.325204252236754,
    "attribute_raw": 0.23545172724238964,
    "profile_match": 1.284135952480367,
    "quality": 27.0213313892136,
    "contradictions": -4.314578338439157,
    "budget_penalty": 0.0,
    "novelty_penalty": -1.9312692624384888,
}


class PreciseReranker:
    """Feature-scored precise ranker.

    Same CandidateRanker contract as FallbackReranker. Adds: bayesian-shrunk
    quality (average_rating x rating_number instead of rating_number alone),
    explicit soft-constraint contradiction detection (material/color/style/
    use_case/brand, not just budget), and a continuous budget penalty instead
    of a flat one. Recall-signal handling (rrf/dense/attribute/lexical) and
    term coverage intentionally mirror FallbackReranker's scale -- see
    docs/precise_reranker_change_report.md for why an earlier normalized/
    batch-idf version regressed and was reverted.

    Pass `catalog_products` (a CatalogIndex.products-shaped dict) once at
    construction to enable proper corpus-wide idf weighting for term_coverage
    / profile_match; without it, term coverage falls back to a plain overlap
    ratio (same as FallbackReranker), which is still correct, just less
    precise about which terms are actually rare.
    """

    def __init__(
        self,
        weights: dict[str, float] | None = None,
        catalog_products: dict[str, dict[str, Any]] | None = None,
    ) -> None:
        self.weights = {**DEFAULT_WEIGHTS, **(weights or {})}
        self.idf = build_global_idf(catalog_products) if catalog_products else None

    def rank(
        self,
        candidates: list[dict[str, Any]],
        *,
        query: str,
        category: str,
        constraints: list[Constraint],
        profile: dict[str, Any] | None = None,
        previously_recommended: set[str] | None = None,
    ) -> list[dict[str, Any]]:
        if not candidates:
            return []

        features = extract_batch_features(
            candidates,
            query=query,
            category=category,
            constraints=constraints,
            profile=profile,
            previously_recommended=previously_recommended,
            idf=self.idf,
        )

        w = self.weights
        ranked: list[dict[str, Any]] = []
        for candidate, feat in zip(candidates, features):
            score = (
                w["exact_matches"] * feat.exact_matches
                + w["partial_matches"] * feat.partial_matches
                + w["category_match"] * feat.category_match
                + w["term_coverage"] * feat.term_coverage
                + w["lexical_signal"] * feat.lexical_signal
                + w["rrf_raw"] * feat.rrf_raw
                + w["dense_raw"] * feat.dense_raw
                + w["attribute_raw"] * feat.attribute_raw
                + w["profile_match"] * feat.profile_match
                + w["quality"] * feat.quality
                + w["contradictions"] * feat.contradictions
                + w["budget_penalty"] * feat.budget_penalty
                + w["novelty_penalty"] * feat.novelty_penalty
            )
            ranked.append({
                **candidate,
                "reranker_score": score,
                "reranker_explanation": feat.explanations,
            })

        ranked.sort(
            key=lambda item: (
                -float(item["reranker_score"]),
                int(item.get("lexical_rank") or 999999),
            )
        )
        return ranked
